INSERT INTO reference."assistant_faq" ("intent", "language", "category", "questions", "answer", "reply_type", "action", "is_active", "sort_order") VALUES
  ('about_anava', 'en', 'About ANAVA', ARRAY['What is ANAVA?', 'Tell me about ANAVA', 'What is ANAVA Clinics?', 'Who are you?', 'What does ANAVA do?']::text[], 'ANAVA Clinics Pvt Ltd offers clinically supervised, non-invasive brain stimulation (neurotherapy) in Pune, for conditions such as depression, anxiety, chronic pain, insomnia, Parkinson''s, dementia and stroke recovery. Nothing is implanted and no anaesthesia is needed. A software platform connects patients, clinicians and care.', 'faq', NULL, true, 910),
  ('anava_treatments', 'en', 'About ANAVA', ARRAY['What treatments does ANAVA offer?', 'What is tDCS?', 'What is tVNS?', 'Do you offer TMS?', 'Which treatments are available?']::text[], 'ANAVA currently offers tDCS (transcranial direct current stimulation) and tVNS (transcutaneous auricular vagus nerve stimulation). TMS and TPS are listed as coming soon. Sessions typically last 20 to 60 minutes depending on the treatment. Only a clinician can say which one suits you, after an assessment.', 'faq', NULL, true, 920),
  ('anava_founders', 'en', 'About ANAVA', ARRAY['Who founded ANAVA?', 'Who are the founders of ANAVA?', 'Who owns ANAVA?', 'Who started ANAVA?']::text[], 'ANAVA Clinics was founded by Vaasudev Chandani (Co-Founder and Chief Technology Officer) and Anu Shadeja (Co-Founder and Chief Operating Officer).', 'faq', NULL, true, 930),
  ('anava_director', 'en', 'About ANAVA', ARRAY['Who is the director of ANAVA?', 'Who is the CEO of ANAVA?', 'Who runs ANAVA?', 'Who is the head of ANAVA?', 'Who is the leadership team?']::text[], 'ANAVA''s website lists two co-founders: Vaasudev Chandani (Co-Founder and Chief Technology Officer) and Anu Shadeja (Co-Founder and Chief Operating Officer). It does not list a separate director. To see your own doctor, ask me "Who is my doctor?".', 'faq', 'care_team', true, 940),
  ('anava_doctors', 'en', 'About ANAVA', ARRAY['Who are the doctors at ANAVA?', 'Who is the clinical team?', 'Which specialists work with ANAVA?']::text[], 'ANAVA works with a network of affiliated specialists, for example Prerna Shah (M.S. in Counselling and Psychotherapy). The network is growing. Your own care team is shown in the app.', 'faq', 'care_team', true, 950),
  ('anava_location', 'en', 'About ANAVA', ARRAY['Where is ANAVA located?', 'Where is the ANAVA registered office?', 'What is the ANAVA address?']::text[], 'ANAVA''s first clinic is in Pune. The registered office is at One North Apartment, H1601, Magarpatta, Hadapsar I.E., Pune City, Pune 411013, Maharashtra. Your own clinic''s address is in the app.', 'faq', 'clinic_map', true, 960),
  ('anava_contact', 'en', 'About ANAVA', ARRAY['How do I contact ANAVA?', 'What is the ANAVA email?', 'What is the ANAVA phone number?', 'ANAVA customer care number']::text[], 'You can call ANAVA on +91 724-9310743 or write to contact@anavaclinics.com. For refunds write to contact@anavaclinics.com with the subject "Refund request". For privacy matters write to privacy@anavaclinics.com.', 'faq', 'call_clinic', true, 970),
  ('anava_fees_start', 'en', 'About ANAVA', ARRAY['How much does a session cost?', 'What are the fees?', 'What is the price of tDCS?']::text[], 'tDCS fees start at ₹1,500 per session. The exact charge depends on the clinic and appointment type, and it is shown before you confirm a booking.', 'faq', NULL, true, 980),
  ('anava_not_cure', 'en', 'About ANAVA', ARRAY['Is neurotherapy a cure?', 'Does brain stimulation work for everyone?', 'Can ANAVA guarantee results?']::text[], 'Neuromodulation is not a cure and does not work for everyone. No result can be promised. Your clinician decides whether it suits you, after an assessment.', 'faq', NULL, true, 990),
  ('anava_medical_disclaimer', 'en', 'About ANAVA', ARRAY['What is the medical disclaimer?', 'Is the ANAVA website medical advice?']::text[], 'The ANAVA website is general information only. It is not a diagnosis or treatment advice, and reading it or sending an enquiry does not create a doctor–patient relationship. Never stop, start or change medicine because of the website. In an emergency call your local emergency number. Tele-MANAS is available 24 hours on 14416.', 'faq', NULL, true, 1000),
  ('refund_policy_summary', 'en', 'Refunds and cancellation', ARRAY['Explain the refund policy', 'What is the refund policy?', 'Tell me about refunds', 'Cancellation and refund policy']::text[], 'Cancel or reschedule 6 or more hours before your appointment and the full amount is refunded or carried to the new slot. Less than 6 hours before, or a no-show, a cancellation charge applies (shown at booking). If ANAVA cancels, you can choose a new slot or a full refund. Completed sessions are not refunded. Approved refunds reach your original payment method in 5–7 business days.', 'faq', 'refund_policy', true, 1010),
  ('refund_when_full', 'en', 'Refunds and cancellation', ARRAY['When do I get a full refund?', 'Am I eligible for a full refund?']::text[], 'A full refund applies when you cancel 6 or more hours before the slot, when ANAVA cancels or cannot deliver the appointment, and for duplicate payments or payments where the booking was not confirmed.', 'faq', 'refund_policy', true, 1020),
  ('refund_when_partial', 'en', 'Refunds and cancellation', ARRAY['When do I get a partial refund?', 'What if I cancel at the last minute?', 'What is the cancellation charge?']::text[], 'If you cancel less than 6 hours before, you get the amount paid minus the cancellation charge for your clinic and appointment type. The charge is shown at booking. For prepaid multi-session plans, unused sessions are refunded as per the plan terms shown when you bought it.', 'faq', 'refund_policy', true, 1030),
  ('refund_when_none', 'en', 'Refunds and cancellation', ARRAY['When is there no refund?', 'Can I get a refund for a completed session?']::text[], 'There is no refund for consultations, assessments or sessions already completed, or for the cancellation charge on late cancellations and missed appointments. Refunds are also not linked to clinical outcomes.', 'faq', 'refund_policy', true, 1040),
  ('refund_timeline_policy', 'en', 'Refunds and cancellation', ARRAY['How long does a refund take?', 'When will I get my refund?']::text[], 'Approved refunds go back to your original payment method within 5–7 business days. Your bank or card issuer may take longer to show it on your statement.', 'faq', 'refund_policy', true, 1050),
  ('refund_request_how', 'en', 'Refunds and cancellation', ARRAY['How do I request a refund?', 'How do I claim a refund?']::text[], 'Email contact@anavaclinics.com with the subject "Refund request". Include your name, the phone or email used for booking, the booking ID, appointment date, time and clinic, the payment reference if you have it, and a short reason. ANAVA acknowledges requests within one working day.', 'faq', 'refund_policy', true, 1060),
  ('cancel_free_window', 'en', 'Refunds and cancellation', ARRAY['Until when can I cancel for free?', 'Free cancellation time', 'How late can I reschedule without a charge?']::text[], 'You can cancel or reschedule free of charge up to 6 hours before your appointment. After that, a cancellation charge applies.', 'faq', 'appointment_detail', true, 1070),
  ('terms_summary', 'en', 'Terms of use', ARRAY['Explain the terms and conditions', 'What are the terms of use?', 'Terms and conditions', 'Summarise the terms']::text[], 'The Terms of Use cover the ANAVA website. Key points: the content is information, not medical advice; you must be 18 or older (younger users need a parent or guardian); you may not scrape, copy or misuse the site; descriptions of services and clinics are indicative; bookings, payments and refunds follow the Refund Policy; the laws of India apply and the courts at Pune have jurisdiction. They were last updated on 15 October 2026.', 'faq', 'terms', true, 1080),
  ('terms_age', 'en', 'Terms of use', ARRAY['What is the minimum age to use ANAVA?', 'Can a child use ANAVA?', 'Can my child be treated at ANAVA?']::text[], 'You must be 18 or older to accept the terms. Under-18s may use ANAVA only with a parent or lawful guardian, who accepts the terms on their behalf.', 'faq', 'terms', true, 1090),
  ('terms_law', 'en', 'Terms of use', ARRAY['Which law applies to ANAVA?', 'Where are disputes settled?', 'What is the jurisdiction?']::text[], 'The terms are governed by the laws of India. The courts at Pune, Maharashtra have exclusive jurisdiction, subject to your right to approach a consumer forum or statutory authority.', 'faq', 'terms', true, 1100),
  ('terms_grievance', 'en', 'Terms of use', ARRAY['Who is the grievance officer?', 'How do I make a complaint?', 'Where can I complain?']::text[], 'The Grievance Officer is Mr. Vaasudev Chandani, Co-Founder. Email grievance@anavaclinics.com (write "Privacy grievance" in the subject for privacy matters) or call +91 724-9310743. Complaints are acknowledged within 48 hours and ANAVA aims to resolve them within 30 days.', 'faq', 'privacy_policy', true, 1110),
  ('privacy_summary', 'en', 'Privacy', ARRAY['Explain the privacy policy', 'What is the privacy policy?', 'Tell me about privacy', 'How is my data used?']::text[], 'ANAVA collects only the data it needs to respond to enquiries, book and manage appointments and payments, deliver and record your care, keep the platform secure, and meet legal duties. Health data is treated as sensitive: it is encrypted, access is limited and logged, and it is never sold or used for marketing. You can ask to access, correct or erase your data at privacy@anavaclinics.com.', 'faq', 'privacy_policy', true, 1120),
  ('privacy_data_collected', 'en', 'Privacy', ARRAY['What data does ANAVA collect?', 'What personal information do you keep?']::text[], 'You give your name, email, phone number, city and health details you choose to share. ANAVA also creates clinical and treatment records, and the website records technical details such as IP address and browser. ANAVA says it does not buy data from brokers or build advertising profiles.', 'faq', 'privacy_policy', true, 1130),
  ('privacy_sharing', 'en', 'Privacy', ARRAY['Do you sell my data?', 'Who is my data shared with?', 'Is my data shared with others?']::text[], 'No. ANAVA does not sell, rent or trade personal data. It is shared only with your treating clinicians when needed for care, service providers such as hosting, email and payments under written contracts, professional advisers, and authorities when the law requires.', 'faq', 'privacy_policy', true, 1140),
  ('privacy_security', 'en', 'Privacy', ARRAY['Is my data safe?', 'How is my data protected?', 'Is my health data secure?']::text[], 'Data is encrypted in transit and at rest, access is role-based and limited to those who need it, administrative and clinical access uses multi-factor authentication, every access to a clinical record is logged, and backups are tested. ANAVA aims to store data in India.', 'faq', 'privacy_policy', true, 1150),
  ('privacy_retention', 'en', 'Privacy', ARRAY['How long is my data kept?', 'How long do you keep my records?']::text[], 'Enquiries that do not lead to care are kept up to 24 months from last contact. Clinical and treatment records are kept as medical record-keeping and limitation laws require. Accounting and tax records are kept as the law requires. After that data is deleted or irreversibly anonymised.', 'faq', 'privacy_policy', true, 1160),
  ('privacy_rights', 'en', 'Privacy', ARRAY['What are my data rights?', 'Can I see my data?', 'Can I correct my data?', 'Can I delete my data?']::text[], 'You can ask to access your data, correct it, erase it where it is no longer needed, withdraw consent, raise a grievance, and nominate someone to act for you. Write to privacy@anavaclinics.com. ANAVA verifies your identity, replies within 30 days and does not charge. For deleting your account, use the Delete account screen in your profile.', 'faq', 'delete_account', true, 1170),
  ('privacy_children', 'en', 'Privacy', ARRAY['Is my child''s data safe?', 'Do you collect data from children?']::text[], 'ANAVA does not knowingly collect data from anyone under 18 through its website. For minors receiving care, data is processed only with verifiable parent or guardian consent.', 'faq', 'privacy_policy', true, 1180),
  ('privacy_cookies', 'en', 'Privacy', ARRAY['Do you use cookies?', 'Does ANAVA track me?']::text[], 'The website uses only necessary cookies for functionality and security. There are no advertising or cross-site tracking cookies, and website data is not sold.', 'faq', 'privacy_policy', true, 1190),
  ('privacy_breach', 'en', 'Privacy', ARRAY['What if my data is leaked?', 'What happens in a data breach?']::text[], 'If there is a data breach, ANAVA notifies the people affected and the Data Protection Board of India as the law requires, and explains what happened, the likely effect, the steps taken and what you can do.', 'faq', 'privacy_policy', true, 1200),
  ('privacy_withdraw_consent', 'en', 'Privacy', ARRAY['How do I withdraw my consent?', 'Can I take back my consent?']::text[], 'You can ask at any time by writing to contact@anavaclinics.com, marked for the Grievance Officer. After withdrawal the related processing stops and data is deleted or anonymised, unless the law requires it to be kept. ANAVA tells you which applies.', 'faq', 'profile_consents', true, 1210)
