-- 127_assistant_faq_website.sql
--
-- APPLY ORDER: after 126. Idempotent. Plain data seed, no alembic revision.
--
-- 31 English FAQ rows written from the public ANAVA website (anavaclinics.com: refund-policy, terms-of-use,
-- privacy-policy, medical-disclaimer, about, home), read on 2026-10-24. Policies were last updated 15 October 2026.
-- Every row is ACTIVE because it restates published text. Re-check against the website when a policy changes and
-- re-run; a row that has approved_by / approved_at set is never overwritten by a re-run.
-- The website lists no directors: only the two co-founders. Do not add a director without confirming it.

SET client_encoding = 'UTF8';

BEGIN;

ON CONFLICT ("intent", "language") DO UPDATE SET
    "category" = EXCLUDED."category", "questions" = EXCLUDED."questions", "answer" = EXCLUDED."answer",
    "reply_type" = EXCLUDED."reply_type", "action" = EXCLUDED."action", "is_active" = EXCLUDED."is_active",
    "sort_order" = EXCLUDED."sort_order", "updated_at" = now()
    WHERE reference."assistant_faq"."approved_by" IS NULL AND reference."assistant_faq"."approved_at" IS NULL;

COMMIT;
